  "value": "{\"internal/chat/loading_indicators.go\":\"// Package chat provides chat UI components\\npackage chat\\n\\nimport (\\n\\t\\\"fmt\\\"\\n\\t\\\"math\\\"\\n\\t\\\"strings\\\"\\n\\t\\\"sync\\\"\\n\\t\\\"time\\\"\\n\\n\\ttea \\\"charm.land/bubbletea/v2\\\"\\n\\t\\\"charm.land/lipgloss/v2\\\"\\n\\t\\\"github.com/Swarm-Code/mono/swarm-sdk/swarm-tui/internal/i18n\\\"\\n)\\n\\n// LoadingRefreshMsg is DEPRECATED - use AnimationTickMsg instead\\ntype LoadingRefreshMsg struct{}\\n\\n// LoadingIndicatorType represents different types of loading animations\\ntype LoadingIndicatorType int\\n\\nconst (\\n\\tLoadingSpinner LoadingIndicatorType = iota\\n\\tLoadingDots\\n\\tLoadingGlitch\\n\\tLoadingPulse\\n\\tLoadingBar\\n)\\n\\n// LoadingIndicator is a lightweight loading animation renderer\\n// It does NOT have its own goroutine - it uses the shared AnimationClock\\ntype LoadingIndicator struct {\\n\\tindicatorType   LoadingIndicatorType\\n\\tindicatorTypeMu sync.RWMutex\\n\\tlabel           string\\n\\tlabelMu         sync.RWMutex\\n\\tWidth           int\\n\\tTheme           Theme\\n\\n\\tisActive  bool\\n\\tactiveMu  sync.RWMutex\\n\\tstartTime time.Time\\n\\n\\t// Determinate progress support (0.0-1.0). When hasProgress is false the\\n\\t// indicator falls back to its existing indeterminate rendering.\\n\\tprogress    float64\\n\\thasProgress bool\\n\\tprogressMu  sync.RWMutex\\n\\n\\t// Pre-created styles to avoid allocations per frame\\n\\taccentStyle  lipgloss.Style\\n\\ttextStyle    lipgloss.Style\\n\\tmutedStyle   lipgloss.Style\\n\\tprimaryStyle lipgloss.Style\\n\\tborderStyle  lipgloss.Style\\n\\terrorStyle   lipgloss.Style\\n\\tstylesInited bool\\n\\n\\t// Render cache to skip identical frames\\n\\tlastFrame int\\n}\\n\\n// NewLoadingIndicator creates a new loading indicator\\nfunc NewLoadingIndicator(indicatorType LoadingIndicatorType, label string, theme Theme) *LoadingIndicator {\\n\\tli := &LoadingIndicator{\\n\\t\\tindicatorType: indicatorType,\\n\\t\\tlabel:         label,\\n\\t\\tWidth:         40,\\n\\t\\tTheme:         theme,\\n\\t\\tlastFrame:     -1, // Invalid frame to force first render\\n\\t}\\n\\tli.initStyles()\\n\\treturn li\\n}\\n\\n// initStyles pre-creates all styles to avoid allocations during rendering\\nfunc (li *LoadingIndicator) initStyles() {\\n\\tif li.stylesInited {\\n\\t\\treturn\\n\\t}\\n\\tli.accentStyle = lipgloss.NewStyle().Foreground(lipgloss.Color(li.Theme.Accent))\\n\\tli.textStyle = lipgloss.NewStyle().Foreground(lipgloss.Color(li.Theme.Text))\\n\\tli.mutedStyle = lipgloss.NewStyle().Foreground(lipgloss.Color(li.Theme.TextMuted))\\n\\tli.primaryStyle = lipgloss.NewStyle().Foreground(lipgloss.Color(li.Theme.Primary))\\n\\tli.borderStyle = lipgloss.NewStyle().Foreground(lipgloss.Color(li.Theme.Border))\\n\\tli.errorStyle = lipgloss.NewStyle().Foreground(lipgloss.Color(li.Theme.Error)).Bold(true)\\n\\tli.stylesInited = true\\n}\\n\\n// Start activates the loading indicator\\n// Returns a tea.Cmd to start the animation tick chain if this is the first subscriber\\nfunc (li *LoadingIndicator) Start(clock *AnimationClock) tea.Cmd {\\n\\tli.activeMu.Lock()\\n\\twasActive := li.isActive\\n\\tli.isActive = true\\n\\tli.startTime = time.Now()\\n\\tli.activeMu.Unlock()\\n\\n\\tif !wasActive && clock != nil {\\n\\t\\treturn clock.Subscribe()\\n\\t}\\n\\treturn nil\\n}\\n\\n// Stop deactivates the loading indicator\\nfunc (li *LoadingIndicator) Stop(clock *AnimationClock) {\\n\\tli.activeMu.Lock()\\n\\twasActive := li.isActive\\n\\tli.isActive = false\\n\\tli.activeMu.Unlock()\\n\\n\\tif wasActive && clock != nil {\\n\\t\\tclock.Unsubscribe()\\n\\t}\\n}\\n\\n// SetText updates the loading indicator's label text\\nfunc (li *LoadingIndicator) SetText(label string) {\\n\\tli.labelMu.Lock()\\n\\tli.label = label\\n\\tli.labelMu.Unlock()\\n}\\n\\n// SetProgress sets a determinate progress percentage (0.0-1.0), clamping\\n// out-of-range values. Once set, LoadingBar indicators render a filled\\n// percentage bar instead of the indeterminate ping-pong animation.\\nfunc (li *LoadingIndicator) SetProgress(pct float64) {\\n\\tif pct < 0 {\\n\\t\\tpct = 0\\n\\t} else if pct > 1 {\\n\\t\\tpct = 1\\n\\t}\\n\\tli.progressMu.Lock()\\n\\tli.progress = pct\\n\\tli.hasProgress = true\\n\\tli.progressMu.Unlock()\\n}\\n\\n// ClearProgress resets the indicator back to indeterminate mode, allowing\\n// the same LoadingIndicator to be reused across determinate/indeterminate\\n// phases (e.g. compacting vs. non-compacting states).\\nfunc (li *LoadingIndicator) ClearProgress() {\\n\\tli.progressMu.Lock()\\n\\tli.progress = 0\\n\\tli.hasProgress = false\\n\\tli.progressMu.Unlock()\\n}\\n\\n// GetProgress returns the current progress percentage and whether a\\n// determinate percentage has been set via SetProgress.\\nfunc (li *LoadingIndicator) GetProgress() (pct float64, ok bool) {\\n\\tli.progressMu.RLock()\\n\\tdefer li.progressMu.RUnlock()\\n\\treturn li.progress, li.hasProgress\\n}\\n\\n// IsActive returns whether the indicator is running\\nfunc (li *LoadingIndicator) IsActive() bool {\\n\\tli.activeMu.RLock()\\n\\tdefer li.activeMu.RUnlock()\\n\\treturn li.isActive\\n}\\n\\n// View renders the current loading indicator state\\nfunc (li *LoadingIndicator) View(clock *AnimationClock) string {\\n\\tif !li.IsActive() {\\n\\t\\treturn \\\"\\\"\\n\\t}\\n\\n\\tframe := 0\\n\\tif clock != nil {\\n\\t\\tframe = clock.Frame()\\n\\t}\\n\\n\\tswitch li.GetIndicatorType() {\\n\\tcase LoadingSpinner:\\n\\t\\treturn li.renderSpinner(frame)\\n\\tcase LoadingDots:\\n\\t\\treturn li.renderDots(frame)\\n\\tcase LoadingGlitch:\\n\\t\\treturn li.renderGlitch(frame)\\n\\tcase LoadingPulse:\\n\\t\\treturn li.renderPulse(frame)\\n\\tcase LoadingBar:\\n\\t\\tif pct, ok := li.GetProgress(); ok {\\n\\t\\t\\t_ = pct\\n\\t\\t\\treturn li.renderProgressBar(frame)\\n\\t\\t}\\n\\t\\treturn li.renderBar(frame)\\n\\tdefault:\\n\\t\\treturn li.renderSpinner(frame)\\n\\t}\\n}\\n\\n// ViewWithTime renders the indicator with elapsed time\\nfunc (li *LoadingIndicator) ViewWithTime(clock *AnimationClock) string {\\n\\tindicator := li.View(clock)\\n\\telapsed := li.GetElapsedTimeString()\\n\\n\\tif elapsed != \\\"\\\" {\\n\\t\\treturn fmt.Sprintf(\\\"%s %s\\\", indicator, li.mutedStyle.Render(elapsed))\\n\\t}\\n\\n\\treturn indicator\\n}\\n\\n// getLabel returns the current label\\nfunc (li *LoadingIndicator) getLabel() string {\\n\\tli.labelMu.RLock()\\n\\tdefer li.labelMu.RUnlock()\\n\\treturn li.label\\n}\\n\\n// renderSpinner creates a rotating spinner\\nfunc (li *LoadingIndicator) renderSpinner(frame int) string {\\n\\tspinners := []string{\\\"⠋\\\", \\\"⠙\\\", \\\"⠹\\\", \\\"⠸\\\", \\\"⠼\\\", \\\"⠴\\\", \\\"⠦\\\", \\\"⠧\\\", \\\"⠇\\\", \\\"⠏\\\"}\\n\\tspinner := spinners[frame%len(spinners)]\\n\\n\\tspinnerText := li.accentStyle.Render(spinner)\\n\\n\\tlabel := li.getLabel()\\n\\tif label != \\\"\\\" {\\n\\t\\treturn fmt.Sprintf(\\\"%s %s\\\", spinnerText, li.mutedStyle.Render(label))\\n\\t}\\n\\n\\treturn spinnerText\\n}\\n\\n// renderDots creates animated dots with fixed width\\nfunc (li *LoadingIndicator) renderDots(frame int) string {\\n\\tconst maxDots = 6\\n\\tdotCount := (frame / 6) % (maxDots + 1)\\n\\tdots := strings.Repeat(\\\"·\\\", dotCount)\\n\\tpadding := strings.Repeat(\\\" \\\", maxDots-dotCount)\\n\\n\\tlabel := li.getLabel()\\n\\tif label != \\\"\\\" {\\n\\t\\treturn fmt.Sprintf(\\\"%s%s%s\\\", li.textStyle.Render(label), li.accentStyle.Render(dots), padding)\\n\\t}\\n\\n\\treturn li.accentStyle.Render(dots) + padding\\n}\\n\\n// renderGlitch creates a glitch text effect\\nfunc (li *LoadingIndicator) renderGlitch(frame int) string {\\n\\tglitchChars := []rune{'█', '░', '▒', '▓', '▀', '▄', '▌', '▐', '■', '□', '▪', '▫'}\\n\\n\\tbaseText := li.getLabel()\\n\\tif baseText == \\\"\\\" {\\n\\t\\tbaseText = i18n.T(\\\"classic_chat_2.loading.processing_upper\\\")\\n\\t}\\n\\n\\tvar glitchText strings.Builder\\n\\tglitchText.Grow(len(baseText) * 4) // Pre-allocate\\n\\n\\tfor i, char := range baseText {\\n\\t\\tif (frame+i)%15 == 0 {\\n\\t\\t\\tglitchChar := glitchChars[(frame+i)%len(glitchChars)]\\n\\t\\t\\tglitchText.WriteString(li.errorStyle.Render(string(glitchChar)))\\n\\t\\t} else if (frame+i)%7 == 0 {\\n\\t\\t\\tglitchText.WriteString(li.accentStyle.Render(string(char)))\\n\\t\\t} else {\\n\\t\\t\\tglitchText.WriteString(li.textStyle.Render(string(char)))\\n\\t\\t}\\n\\t}\\n\\n\\treturn glitchText.String()\\n}\\n\\n// renderPulse creates a pulsing indicator\\nfunc (li *LoadingIndicator) renderPulse(frame int) string {\\n\\tintensity := (math.Sin(float64(frame)*0.2) + 1) / 2\\n\\n\\tvar pulseChar string\\n\\tvar pulseStyle lipgloss.Style\\n\\tif intensity > 0.7 {\\n\\t\\tpulseChar = \\\"●\\\"\\n\\t\\tpulseStyle = li.accentStyle\\n\\t} else if intensity > 0.4 {\\n\\t\\tpulseChar = \\\"◐\\\"\\n\\t\\tpulseStyle = li.primaryStyle\\n\\t} else {\\n\\t\\tpulseChar = \\\"○\\\"\\n\\t\\tpulseStyle = li.mutedStyle\\n\\t}\\n\\n\\tpulseText := pulseStyle.Render(pulseChar)\\n\\n\\tlabel := li.getLabel()\\n\\tif label != \\\"\\\" {\\n\\t\\treturn fmt.Sprintf(\\\"%s %s\\\", pulseText, li.textStyle.Render(label))\\n\\t}\\n\\n\\treturn pulseText\\n}\\n\\n// renderBar creates an animated progress bar\\nfunc (li *LoadingIndicator) renderBar(frame int) string {\\n\\tbarWidth := 20\\n\\tif li.Width > 0 {\\n\\t\\tbarWidth = li.Width\\n\\t}\\n\\n\\tposition := frame % (barWidth * 2)\\n\\tif position >= barWidth {\\n\\t\\tposition = barWidth*2 - position - 1\\n\\t}\\n\\n\\tvar bar strings.Builder\\n\\tbar.Grow(barWidth * 4) // Pre-allocate\\n\\n\\tfor i := 0; i < barWidth; i++ {\\n\\t\\tdist := abs(i - position)\\n\\t\\tif dist <= 1 {\\n\\t\\t\\tbar.WriteString(li.accentStyle.Render(\\\"█\\\"))\\n\\t\\t} else if dist <= 2 {\\n\\t\\t\\tbar.WriteString(li.primaryStyle.Render(\\\"▓\\\"))\\n\\t\\t} else {\\n\\t\\t\\tbar.WriteString(li.borderStyle.Render(\\\"░\\\"))\\n\\t\\t}\\n\\t}\\n\\n\\tresult := bar.String()\\n\\tlabel := li.getLabel()\\n\\tif label != \\\"\\\" {\\n\\t\\tresult = fmt.Sprintf(\\\"%s %s\\\", li.textStyle.Render(label), result)\\n\\t}\\n\\n\\treturn result\\n}\\n\\n// renderProgressBar creates a determinate left-to-right filled progress bar\\n// based on the percentage set via SetProgress, along with a trailing\\n// percentage label (e.g. \\\" 42%\\\").\\nfunc (li *LoadingIndicator) renderProgressBar(frame int) string {\\n\\t_ = frame // determinate render does not depend on animation frame\\n\\n\\tbarWidth := 20\\n\\tif li.Width > 0 {\\n\\t\\tbarWidth = li.Width\\n\\t}\\n\\n\\tpct, _ := li.GetProgress()\\n\\tfilled := int(math.Round(pct * float64(barWidth)))\\n\\tif filled < 0 {\\n\\t\\tfilled = 0\\n\\t} else if filled > barWidth {\\n\\t\\tfilled = barWidth\\n\\t}\\n\\n\\tvar bar strings.Builder\\n\\tbar.Grow(barWidth*4 + 8) // Pre-allocate\\n\\n\\tif filled > 0 {\\n\\t\\tbar.WriteString(li.accentStyle.Render(strings.Repeat(\\\"█\\\", filled)))\\n\\t}\\n\\tif barWidth-filled > 0 {\\n\\t\\tbar.WriteString(li.borderStyle.Render(strings.Repeat(\\\"░\\\", barWidth-filled)))\\n\\t}\\n\\n\\tpercentLabel := fmt.Sprintf(\\\" %3d%%\\\", int(math.Round(pct*100)))\\n\\tresult := bar.String() + li.mutedStyle.Render(percentLabel)\\n\\n\\tlabel := li.getLabel()\\n\\tif label != \\\"\\\" {\\n\\t\\tresult = fmt.Sprintf(\\\"%s %s\\\", li.textStyle.Render(label), result)\\n\\t}\\n\\n\\treturn result\\n}\\n\\n// GetElapsedTime returns the time since the indicator started\\nfunc (li *LoadingIndicator) GetElapsedTime() time.Duration {\\n\\tif !li.IsActive() {\\n\\t\\treturn 0\\n\\t}\\n\\tli.activeMu.RLock()\\n\\tstartTime := li.startTime\\n\\tli.activeMu.RUnlock()\\n\\treturn time.Since(startTime)\\n}\\n\\n// GetElapsedTimeString returns a formatted elapsed time string\\nfunc (li *LoadingIndicator) GetElapsedTimeString() string {\\n\\telapsed := li.GetElapsedTime()\\n\\tif elapsed < time.Second {\\n\\t\\treturn \\\"\\\"\\n\\t}\\n\\n\\tseconds := int(elapsed.Seconds())\\n\\tif seconds < 60 {\\n\\t\\treturn fmt.Sprintf(\\\"(%ds)\\\", seconds)\\n\\t}\\n\\n\\tminutes := seconds / 60\\n\\tremainingSeconds := seconds % 60\\n\\treturn fmt.Sprintf(\\\"(%dm%ds)\\\", minutes, remainingSeconds)\\n}\\n\\n// CycleIndicatorType cycles to the next loading indicator type\\nfunc (li *LoadingIndicator) CycleIndicatorType() {\\n\\tswitch li.GetIndicatorType() {\\n\\tcase LoadingSpinner:\\n\\t\\tli.SetIndicatorType(LoadingDots)\\n\\t\\tli.SetText(i18n.T(\\\"classic_chat_2.loading.agent_working\\\"))\\n\\tcase LoadingDots:\\n\\t\\tli.SetIndicatorType(LoadingGlitch)\\n\\t\\tli.SetText(i18n.T(\\\"classic_chat_2.loading.processing_upper\\\"))\\n\\tcase LoadingGlitch:\\n\\t\\tli.SetIndicatorType(LoadingPulse)\\n\\t\\tli.SetText(i18n.T(\\\"classic_chat_2.loading.agent_thinking\\\"))\\n\\tcase LoadingPulse:\\n\\t\\tli.SetIndicatorType(LoadingBar)\\n\\t\\tli.SetText(i18n.T(\\\"classic_chat_2.loading.processing\\\"))\\n\\tcase LoadingBar:\\n\\t\\tli.SetIndicatorType(LoadingSpinner)\\n\\t\\tli.SetText(i18n.T(\\\"classic_chat_2.loading.agent_thinking\\\"))\\n\\t}\\n}\\n\\n// SetIndicatorType changes the active animation style. Thread-safe: may be\\n// called from a background tea.Cmd goroutine (e.g. compaction progress\\n// reporting) while View() renders concurrently from the Update loop.\\nfunc (li *LoadingIndicator) SetIndicatorType(t LoadingIndicatorType) {\\n\\tli.indicatorTypeMu.Lock()\\n\\tli.indicatorType = t\\n\\tli.indicatorTypeMu.Unlock()\\n}\\n\\n// GetIndicatorType returns the active animation style. Thread-safe.\\nfunc (li *LoadingIndicator) GetIndicatorType() LoadingIndicatorType {\\n\\tli.indicatorTypeMu.RLock()\\n\\tdefer li.indicatorTypeMu.RUnlock()\\n\\treturn li.indicatorType\\n}\\n\\n// GetIndicatorTypeString returns the name of the current indicator type\\nfunc (li *LoadingIndicator) GetIndicatorTypeString() string {\\n\\tswitch li.GetIndicatorType() {\\n\\tcase LoadingSpinner:\\n\\t\\treturn i18n.T(\\\"classic_chat_2.loading.spinner\\\")\\n\\tcase LoadingDots:\\n\\t\\treturn i18n.T(\\\"classic_chat_2.loading.dots\\\")\\n\\tcase LoadingGlitch:\\n\\t\\treturn i18n.T(\\\"classic_chat_2.loading.glitch\\\")\\n\\tcase LoadingPulse:\\n\\t\\treturn i18n.T(\\\"classic_chat_2.loading.pulse\\\")\\n\\tcase LoadingBar:\\n\\t\\treturn i18n.T(\\\"classic_chat_2.loading.bar\\\")\\n\\tdefault:\\n\\t\\treturn i18n.T(\\\"classic_chat_2.common.unknown\\\")\\n\\t}\\n}\\n\\n// Note: abs() function is already defined in app.go\\n\",\"internal/chat/spinner.go\":\"// Package chat provides chat UI components\\npackage chat\\n\\nimport (\\n\\t\\\"math\\\"\\n\\t\\\"strconv\\\"\\n\\t\\\"strings\\\"\\n\\t\\\"sync\\\"\\n\\t\\\"time\\\"\\n\\n\\ttea \\\"charm.land/bubbletea/v2\\\"\\n\\t\\\"charm.land/lipgloss/v2\\\"\\n\\t\\\"github.com/Swarm-Code/mono/swarm-sdk/swarm-tui/internal/ui/palette\\\"\\n)\\n\\n// SpinnerType defines the animation style\\ntype SpinnerType int\\n\\nconst (\\n\\tSpinnerTypeMatrix  SpinnerType = iota // Random hex chars with gradient (default)\\n\\tSpinnerTypeBraille                    // Classic braille dots\\n\\tSpinnerTypeBlocks                     // Block building animation\\n\\tSpinnerTypeWave                       // Wave pattern\\n\\tSpinnerTypePulse                      // Pulsing circles\\n\\tSpinnerTypeBounce                     // Bouncing ball\\n\\tSpinnerTypeAurora                     // Aurora borealis effect\\n\\tSpinnerTypeDNA                        // DNA helix pattern\\n)\\n\\n// SpinnerTypeNames maps type to display name\\nvar SpinnerTypeNames = map[SpinnerType]string{\\n\\tSpinnerTypeMatrix:  \\\"Matrix\\\",\\n\\tSpinnerTypeBraille: \\\"Braille\\\",\\n\\tSpinnerTypeBlocks:  \\\"Blocks\\\",\\n\\tSpinnerTypeWave:    \\\"Wave\\\",\\n\\tSpinnerTypePulse:   \\\"Pulse\\\",\\n\\tSpinnerTypeBounce:  \\\"Bounce\\\",\\n\\tSpinnerTypeAurora:  \\\"Aurora\\\",\\n\\tSpinnerTypeDNA:     \\\"DNA Helix\\\",\\n}\\n\\n// SpinnerTypeDescriptions provides descriptions for each type\\nvar SpinnerTypeDescriptions = map[SpinnerType]string{\\n\\tSpinnerTypeMatrix:  \\\"Cyberpunk matrix-style random characters\\\",\\n\\tSpinnerTypeBraille: \\\"Classic minimalist braille dots spinner\\\",\\n\\tSpinnerTypeBlocks:  \\\"Building blocks loading animation\\\",\\n\\tSpinnerTypeWave:    \\\"Smooth wave pattern animation\\\",\\n\\tSpinnerTypePulse:   \\\"Pulsing circles with glow effect\\\",\\n\\tSpinnerTypeBounce:  \\\"Bouncing ball between walls\\\",\\n\\tSpinnerTypeAurora:  \\\"Northern lights color shimmer\\\",\\n\\tSpinnerTypeDNA:     \\\"Double helix DNA strand\\\",\\n}\\n\\n// GetSpinnerTypeFromString converts string to SpinnerType\\nfunc GetSpinnerTypeFromString(s string) SpinnerType {\\n\\tfor t, name := range SpinnerTypeNames {\\n\\t\\tif strings.EqualFold(name, s) {\\n\\t\\t\\treturn t\\n\\t\\t}\\n\\t}\\n\\treturn SpinnerTypeBraille // Default: no random-letter Matrix fallback\\n}\\n\\n// Spinner animation constants\\nconst (\\n\\tspinnerCharCount  = 8\\n\\tellipsisAnimSpeed = 4\\n\\tellipsisMaxDots   = 3\\n)\\n\\n// Spinner is a lightweight animation renderer\\n// It does NOT have its own goroutine or ticker - it uses the shared AnimationClock\\n//\\n// Usage:\\n//\\n//\\tspinner.Start(clock)     // Subscribe to clock, returns tea.Cmd if needed\\n//\\tspinner.View(clock)      // Pure render using clock.Frame()\\n//\\tspinner.Stop(clock)      // Unsubscribe from clock\\ntype Spinner struct {\\n\\tspinnerType SpinnerType\\n\\ttypeMu      sync.RWMutex\\n\\n\\tlabel   string\\n\\tlabelMu sync.RWMutex\\n\\n\\tisActive  bool\\n\\tactiveMu  sync.RWMutex\\n\\tstartTime time.Time\\n\\n\\t// Pre-created styles to avoid allocations per frame\\n\\tlabelStyle lipgloss.Style\\n\\ttimeStyle  lipgloss.Style\\n\\n\\t// Render cache - skip if same frame and label\\n\\tlastFrame int\\n}\\n\\n// NewSpinner creates a new spinner (lightweight, no goroutines)\\n// Default to Braille which has better terminal compatibility than Matrix\\nfunc NewSpinner() *Spinner {\\n\\treturn &Spinner{\\n\\t\\tspinnerType: SpinnerTypeBraille, // Braille has better terminal compat than Matrix\\n\\t\\tlabelStyle:  lipgloss.NewStyle().Foreground(lipgloss.Color(palette.TextDim)),\\n\\t\\ttimeStyle:   lipgloss.NewStyle().Foreground(lipgloss.Color(palette.TextMuted)),\\n\\t\\tlastFrame:   -1, // Invalid frame to force first render\\n\\t}\\n}\\n\\n// SetType changes the spinner animation type\\nfunc (s *Spinner) SetType(t SpinnerType) {\\n\\ts.typeMu.Lock()\\n\\ts.spinnerType = t\\n\\ts.typeMu.Unlock()\\n}\\n\\n// GetType returns the current spinner type\\nfunc (s *Spinner) GetType() SpinnerType {\\n\\ts.typeMu.RLock()\\n\\tdefer s.typeMu.RUnlock()\\n\\treturn s.spinnerType\\n}\\n\\n// SetLabel updates the spinner label\\nfunc (s *Spinner) SetLabel(label string) {\\n\\ts.labelMu.Lock()\\n\\ts.label = label\\n\\ts.labelMu.Unlock()\\n}\\n\\n// IsActive returns whether the spinner should be displayed\\nfunc (s *Spinner) IsActive() bool {\\n\\ts.activeMu.RLock()\\n\\tdefer s.activeMu.RUnlock()\\n\\treturn s.isActive\\n}\\n\\n// Start activates the spinner and subscribes to the animation clock.\\n// Returns a tea.Cmd if this call starts the clock's refresh chain. Callers that\\n// start spinner state from Update must return/batch this command; otherwise the\\n// spinner can become active without any AnimationTickMsg driving repaint.\\nfunc (s *Spinner) Start(clock *AnimationClock) tea.Cmd {\\n\\ts.activeMu.Lock()\\n\\twasActive := s.isActive\\n\\ts.isActive = true\\n\\ts.startTime = time.Now()\\n\\ts.activeMu.Unlock()\\n\\n\\t// Subscribe to clock if we weren't already active\\n\\tif !wasActive && clock != nil {\\n\\t\\treturn clock.Subscribe()\\n\\t}\\n\\treturn nil\\n}\\n\\n// Stop deactivates the spinner and unsubscribes from the animation clock\\nfunc (s *Spinner) Stop(clock *AnimationClock) {\\n\\ts.activeMu.Lock()\\n\\twasActive := s.isActive\\n\\ts.isActive = false\\n\\ts.activeMu.Unlock()\\n\\n\\t// Unsubscribe from clock if we were active\\n\\tif wasActive && clock != nil {\\n\\t\\tclock.Unsubscribe()\\n\\t}\\n}\\n\\n// View renders the spinner using the current frame from the clock\\n// This is a PURE RENDER FUNCTION - no side effects, no scheduling\\nfunc (s *Spinner) View(clock *AnimationClock) string {\\n\\tif !s.IsActive() {\\n\\t\\treturn \\\"\\\"\\n\\t}\\n\\n\\tframe := 0\\n\\tif clock != nil {\\n\\t\\tframe = clock.Frame()\\n\\t}\\n\\n\\ts.typeMu.RLock()\\n\\tspinnerType := s.spinnerType\\n\\ts.typeMu.RUnlock()\\n\\n\\t// Render animation frame\\n\\tanimation := RenderSpinnerFrame(spinnerType, frame)\\n\\n\\tvar b strings.Builder\\n\\tb.Grow(100) // Pre-allocate\\n\\tb.WriteString(animation)\\n\\n\\t// Add label with fixed-width ellipsis\\n\\ts.labelMu.RLock()\\n\\tlabel := s.label\\n\\ts.labelMu.RUnlock()\\n\\n\\tif label != \\\"\\\" {\\n\\t\\tb.WriteString(\\\" \\\")\\n\\t\\tb.WriteString(s.labelStyle.Render(label))\\n\\n\\t\\tellipsisFrame := (frame / ellipsisAnimSpeed) % (ellipsisMaxDots + 1)\\n\\t\\tdots := strings.Repeat(\\\".\\\", ellipsisFrame)\\n\\t\\tpadding := strings.Repeat(\\\" \\\", ellipsisMaxDots-ellipsisFrame)\\n\\t\\tb.WriteString(s.labelStyle.Render(dots + padding))\\n\\t}\\n\\n\\t// Add elapsed time\\n\\ts.activeMu.RLock()\\n\\tstartTime := s.startTime\\n\\ts.activeMu.RUnlock()\\n\\n\\telapsed := time.Since(startTime)\\n\\tif elapsed >= time.Second {\\n\\t\\ttimeStr := formatElapsedTime(elapsed)\\n\\t\\tb.WriteString(\\\" \\\")\\n\\t\\tb.WriteString(s.timeStyle.Render(timeStr))\\n\\t}\\n\\n\\treturn b.String()\\n}\\n\\n// ViewCompact renders a compact inline spinner for tool calls\\nfunc (s *Spinner) ViewCompact(clock *AnimationClock) string {\\n\\tif !s.IsActive() {\\n\\t\\treturn \\\"●\\\"\\n\\t}\\n\\n\\tframe := 0\\n\\tif clock != nil {\\n\\t\\tframe = clock.Frame()\\n\\t}\\n\\n\\tbraille := []string{\\\"⠋\\\", \\\"⠙\\\", \\\"⠹\\\", \\\"⠸\\\", \\\"⠼\\\", \\\"⠴\\\", \\\"⠦\\\", \\\"⠧\\\", \\\"⠇\\\", \\\"⠏\\\"}\\n\\treturn braille[frame%len(braille)]\\n}\\n\\n// ============================================================================\\n// PURE RENDER FUNCTIONS - No state, no side effects\\n// Given a frame number and type, output a string\\n// ============================================================================\\n\\n// RenderSpinnerFrame is a PURE FUNCTION that renders a spinner frame\\n// It has no side effects and doesn't modify any state\\nfunc RenderSpinnerFrame(spinnerType SpinnerType, frame int) string {\\n\\tswitch spinnerType {\\n\\tcase SpinnerTypeMatrix:\\n\\t\\treturn renderMatrix(frame)\\n\\tcase SpinnerTypeBraille:\\n\\t\\treturn renderBraille(frame)\\n\\tcase SpinnerTypeBlocks:\\n\\t\\treturn renderBlocks(frame)\\n\\tcase SpinnerTypeWave:\\n\\t\\treturn renderWave(frame)\\n\\tcase SpinnerTypePulse:\\n\\t\\treturn renderPulse(frame)\\n\\tcase SpinnerTypeBounce:\\n\\t\\treturn renderBounce(frame)\\n\\tcase SpinnerTypeAurora:\\n\\t\\treturn renderAurora(frame)\\n\\tcase SpinnerTypeDNA:\\n\\t\\treturn renderDNA(frame)\\n\\tdefault:\\n\\t\\treturn renderMatrix(frame)\\n\\t}\\n}\\n\\n// Gradient colors shared by animations\\nvar gradientColors = []string{\\n\\t\\\"#FF6B6B\\\", \\\"#FF8E72\\\", \\\"#FFB07A\\\", \\\"#FFD182\\\",\\n\\t\\\"#E8E46E\\\", \\\"#A8E6CF\\\", \\\"#88D8B0\\\", \\\"#4ECDC4\\\",\\n}\\n\\nfunc renderMatrix(frame int) string {\\n\\tchars := []rune(\\\"0123456789abcdefABCDEF~!@#$%^&*+=\\\")\\n\\tvar b strings.Builder\\n\\tfor i := range spinnerCharCount {\\n\\t\\t// Deterministic \\\"random\\\" based on frame and position\\n\\t\\tcharIdx := (frame*7 + i*13) % len(chars)\\n\\t\\tcolorIdx := i % len(gradientColors)\\n\\t\\tstyle := lipgloss.NewStyle().\\n\\t\\t\\tForeground(lipgloss.Color(gradientColors[colorIdx])).\\n\\t\\t\\tBold(true)\\n\\t\\tb.WriteString(style.Render(string(chars[charIdx])))\\n\\t}\\n\\treturn b.String()\\n}\\n\\nfunc renderBraille(frame int) string {\\n\\tbraille := []string{\\\"⠋\\\", \\\"⠙\\\", \\\"⠹\\\", \\\"⠸\\\", \\\"⠼\\\", \\\"⠴\\\", \\\"⠦\\\", \\\"⠧\\\", \\\"⠇\\\", \\\"⠏\\\"}\\n\\tstyle := lipgloss.NewStyle().\\n\\t\\tForeground(lipgloss.Color(\\\"#4ECDC4\\\")).\\n\\t\\tBold(true)\\n\\treturn style.Render(braille[frame%len(braille)])\\n}\\n\\nfunc renderBlocks(frame int) string {\\n\\tblocks := []string{\\n\\t\\t\\\"▏\\\", \\\"▎\\\", \\\"▍\\\", \\\"▌\\\", \\\"▋\\\", \\\"▊\\\", \\\"▉\\\", \\\"█\\\",\\n\\t\\t\\\"▉\\\", \\\"▊\\\", \\\"▋\\\", \\\"▌\\\", \\\"▍\\\", \\\"▎\\\", \\\"▏\\\", \\\" \\\",\\n\\t}\\n\\tvar b strings.Builder\\n\\tfor i := range spinnerCharCount {\\n\\t\\tidx := (frame + i*2) % len(blocks)\\n\\t\\tcolorIdx := i % len(gradientColors)\\n\\t\\tstyle := lipgloss.NewStyle().Foreground(lipgloss.Color(gradientColors[colorIdx]))\\n\\t\\tb.WriteString(style.Render(blocks[idx]))\\n\\t}\\n\\treturn b.String()\\n}\\n\\nfunc renderWave(frame int) string {\\n\\tchars := []string{\\\"▁\\\", \\\"▂\\\", \\\"▃\\\", \\\"▄\\\", \\\"▅\\\", \\\"▆\\\", \\\"▇\\\", \\\"█\\\"}\\n\\tvar b strings.Builder\\n\\tfor i := range 10 {\\n\\t\\tphase := float64(frame)/5.0 + float64(i)*0.5\\n\\t\\theight := (math.Sin(phase) + 1) / 2\\n\\t\\tidx := int(height * float64(len(chars)-1))\\n\\t\\tcolorIdx := i % len(gradientColors)\\n\\t\\tstyle := lipgloss.NewStyle().Foreground(lipgloss.Color(gradientColors[colorIdx]))\\n\\t\\tb.WriteString(style.Render(chars[idx]))\\n\\t}\\n\\treturn b.String()\\n}\\n\\nfunc renderPulse(frame int) string {\\n\\tcircles := []string{\\\"○\\\", \\\"◔\\\", \\\"◑\\\", \\\"◕\\\", \\\"●\\\", \\\"◕\\\", \\\"◑\\\", \\\"◔\\\"}\\n\\tpulseColors := []string{\\\"#555555\\\", \\\"#666666\\\", \\\"#888888\\\", \\\"#AAAAAA\\\", \\\"#4ECDC4\\\", \\\"#AAAAAA\\\", \\\"#888888\\\", \\\"#666666\\\"}\\n\\tvar b strings.Builder\\n\\tfor i := range 5 {\\n\\t\\tidx := (frame + i*2) % len(circles)\\n\\t\\tstyle := lipgloss.NewStyle().Foreground(lipgloss.Color(pulseColors[idx]))\\n\\t\\tb.WriteString(style.Render(circles[idx]))\\n\\t}\\n\\treturn b.String()\\n}\\n\\nfunc renderBounce(frame int) string {\\n\\twidth := 12\\n\\tpos := frame % (width * 2)\\n\\tif pos >= width {\\n\\t\\tpos = width*2 - pos - 1\\n\\t}\\n\\tvar b strings.Builder\\n\\tfor i := range width {\\n\\t\\tvar char string\\n\\t\\tvar color string\\n\\t\\tif i == pos {\\n\\t\\t\\tchar = \\\"●\\\"\\n\\t\\t\\tcolor = \\\"#4ECDC4\\\"\\n\\t\\t} else if i == pos-1 || i == pos+1 {\\n\\t\\t\\tchar = \\\"○\\\"\\n\\t\\t\\tcolor = \\\"#2A9D8F\\\"\\n\\t\\t} else {\\n\\t\\t\\tchar = \\\"·\\\"\\n\\t\\t\\tcolor = \\\"#333333\\\"\\n\\t\\t}\\n\\t\\tstyle := lipgloss.NewStyle().Foreground(lipgloss.Color(color))\\n\\t\\tif i == pos {\\n\\t\\t\\tstyle = style.Bold(true)\\n\\t\\t}\\n\\t\\tb.WriteString(style.Render(char))\\n\\t}\\n\\treturn b.String()\\n}\\n\\nfunc renderAurora(frame int) string {\\n\\tchars := []string{\\\"░\\\", \\\"▒\\\", \\\"▓\\\", \\\"█\\\", \\\"▓\\\", \\\"▒\\\", \\\"░\\\", \\\" \\\"}\\n\\tauroraColors := []string{\\n\\t\\t\\\"#00FF87\\\", \\\"#00E676\\\", \\\"#1DE9B6\\\", \\\"#64FFDA\\\",\\n\\t\\t\\\"#00BFA5\\\", \\\"#26A69A\\\", \\\"#4DB6AC\\\", \\\"#80CBC4\\\",\\n\\t}\\n\\tvar b strings.Builder\\n\\tfor i := range 12 {\\n\\t\\tcharIdx := (frame/2 + i) % len(chars)\\n\\t\\tcolorIdx := (frame + i) % len(auroraColors)\\n\\t\\tstyle := lipgloss.NewStyle().Foreground(lipgloss.Color(auroraColors[colorIdx]))\\n\\t\\tb.WriteString(style.Render(chars[charIdx]))\\n\\t}\\n\\treturn b.String()\\n}\\n\\nfunc renderDNA(frame int) string {\\n\\twidth := 12\\n\\tvar b strings.Builder\\n\\tfor i := range width {\\n\\t\\tphase := float64(frame)/3.0 + float64(i)*0.5\\n\\t\\ty1 := math.Sin(phase)\\n\\t\\ty2 := math.Sin(phase + math.Pi)\\n\\n\\t\\tvar char string\\n\\t\\tvar color string\\n\\t\\tif y1 > y2 {\\n\\t\\t\\tif y1 > 0.3 {\\n\\t\\t\\t\\tchar = \\\"◉\\\"\\n\\t\\t\\t\\tcolor = \\\"#FF6B6B\\\"\\n\\t\\t\\t} else if y1 > -0.3 {\\n\\t\\t\\t\\tchar = \\\"─\\\"\\n\\t\\t\\t\\tcolor = \\\"#666666\\\"\\n\\t\\t\\t} else {\\n\\t\\t\\t\\tchar = \\\"◎\\\"\\n\\t\\t\\t\\tcolor = \\\"#4ECDC4\\\"\\n\\t\\t\\t}\\n\\t\\t} else {\\n\\t\\t\\tif y2 > 0.3 {\\n\\t\\t\\t\\tchar = \\\"◎\\\"\\n\\t\\t\\t\\tcolor = \\\"#4ECDC4\\\"\\n\\t\\t\\t} else if y2 > -0.3 {\\n\\t\\t\\t\\tchar = \\\"─\\\"\\n\\t\\t\\t\\tcolor = \\\"#666666\\\"\\n\\t\\t\\t} else {\\n\\t\\t\\t\\tchar = \\\"◉\\\"\\n\\t\\t\\t\\tcolor = \\\"#FF6B6B\\\"\\n\\t\\t\\t}\\n\\t\\t}\\n\\t\\tstyle := lipgloss.NewStyle().Foreground(lipgloss.Color(color))\\n\\t\\tb.WriteString(style.Render(char))\\n\\t}\\n\\treturn b.String()\\n}\\n\\n// formatElapsedTime formats duration as (XXs) or (Xm XXs)\\nfunc formatElapsedTime(d time.Duration) string {\\n\\tseconds := int(d.Seconds())\\n\\tif seconds < 60 {\\n\\t\\treturn \\\"(\\\" + padZero(seconds) + \\\"s)\\\"\\n\\t}\\n\\tminutes := seconds / 60\\n\\tsecs := seconds % 60\\n\\treturn \\\"(\\\" + strconv.Itoa(minutes) + \\\"m \\\" + padZero(secs) + \\\"s)\\\"\\n}\\n\\nfunc padZero(n int) string {\\n\\tif n < 10 {\\n\\t\\treturn \\\"0\\\" + string(rune('0'+n))\\n\\t}\\n\\treturn string(rune('0'+n/10)) + string(rune('0'+n%10))\\n}\\n\\n// ============================================================================\\n// LEGACY COMPATIBILITY - These will be removed after migration\\n// ============================================================================\\n\\n// SpinnerRefreshMsg is DEPRECATED - use AnimationTickMsg instead\\ntype SpinnerRefreshMsg struct{}\\n\\n// SpinnerTickMsg is DEPRECATED\\ntype SpinnerTickMsg struct {\\n}\\n\",\"internal/chat/app_chat_render.go\":\"package chat\\n\\nimport (\\n\\t\\\"expvar\\\"\\n\\t\\\"fmt\\\"\\n\\t\\\"sort\\\"\\n\\t\\\"strings\\\"\\n\\t\\\"time\\\"\\n\\n\\t\\\"charm.land/lipgloss/v2\\\"\\n\\t\\\"github.com/Swarm-Code/mono/swarm-sdk/internal/conversation\\\"\\n\\t\\\"github.com/Swarm-Code/mono/swarm-sdk/internal/tools/ii\\\"\\n\\t\\\"github.com/Swarm-Code/mono/swarm-sdk/swarm-tui/internal/chat/toolrender\\\"\\n\\t\\\"github.com/Swarm-Code/mono/swarm-sdk/swarm-tui/internal/i18n\\\"\\n)\\n\\n// Expvar counters — visible at http://localhost:6060/debug/vars\\nvar (\\n\\trenderChatContentCalls    = expvar.NewInt(\\\"render_chat_content_calls\\\")\\n\\trenderChatContentCacheHit = expvar.NewInt(\\\"render_chat_content_cache_hits\\\") // header+divider+viewport cache hits\\n\\trenderViewportCalls       = expvar.NewInt(\\\"render_viewport_calls\\\")\\n\\trenderViewportCacheHit    = expvar.NewInt(\\\"render_viewport_cache_hits\\\")\\n\\n\\t// Viewport cache miss breakdown — tells us WHY the lipgloss re-render runs\\n\\trenderViewportMissContent = expvar.NewInt(\\\"render_viewport_miss_content\\\") // new scroll position or new streaming tokens\\n\\trenderViewportMissSize    = expvar.NewInt(\\\"render_viewport_miss_size\\\")    // terminal resize changed width/height\\n\\n\\t// Rapid-invalidation detector: counts frames where viewport re-rendered\\n\\t// within 32ms of the previous re-render (potential flicker source).\\n\\trenderViewportRapidSeq = expvar.NewInt(\\\"render_viewport_rapid_sequential\\\")\\n\\n\\t// SidePanel flicker tracking\\n\\tsidePanelRenderCalls    = expvar.NewInt(\\\"sidepanel_render_calls\\\")\\n\\tsidePanelCacheHits      = expvar.NewInt(\\\"sidepanel_cache_hits\\\")\\n\\tsidePanelCacheMissCount = expvar.NewInt(\\\"sidepanel_cache_misses\\\")        // track misses to find flicker source\\n\\tsidePanelLastMissReason = expvar.NewString(\\\"sidepanel_last_miss_reason\\\") // what invalidated the cache\\n)\\n\\n// ============================================================================\\n// CHAT SCREEN VIEW\\n// ============================================================================\\n\\nfunc (a *App) viewChat() string {\\n\\t// If a detail viewer is active (Enter-to-view on a bash command or\\n\\t// sub-agent), it takes over the chat area until dismissed with Esc.\\n\\tif a.detailViewer != nil {\\n\\t\\treturn a.detailViewer.View()\\n\\t}\\n\\t// If plan viewer is active (plan submitted for approval), show it instead of chat\\n\\tif a.planViewer != nil && a.planQuestionModal != nil {\\n\\t\\treturn a.planViewer.View()\\n\\t}\\n\\treturn a.renderChatContent()\\n}\\n\\nfunc shouldShowTaskPanel(modalActive, sidePanelToggled bool) bool {\\n\\treturn !modalActive && !sidePanelToggled\\n}\\n\\nfunc writeTaskPanelAboveInput(builder *strings.Builder, taskPanel, topSeparator string) {\\n\\tif taskPanel != \\\"\\\" {\\n\\t\\tbuilder.WriteByte('\\\\n')\\n\\t\\tbuilder.WriteString(taskPanel)\\n\\t}\\n\\tbuilder.WriteByte('\\\\n')\\n\\tbuilder.WriteString(topSeparator)\\n}\\n\\nfunc (a *App) renderChatContent() string {\\n\\tlanguageKey := string(i18n.CurrentLanguage()) + \\\"|\\\"\\n\\tif a.cachedHeaderKey != \\\"\\\" && !strings.HasPrefix(a.cachedHeaderKey, languageKey) {\\n\\t\\ta.cachedHeaderKey = languageKey\\n\\t\\ta.cachedHeaderRendered = \\\"\\\"\\n\\t\\ta.cachedViewportContent = \\\"\\\"\\n\\t\\ta.cachedViewportRendered = \\\"\\\"\\n\\t\\tfor i := range a.messages {\\n\\t\\t\\ta.messages[i].MarkDirty()\\n\\t\\t}\\n\\t} else if a.cachedHeaderKey == \\\"\\\" {\\n\\t\\ta.cachedHeaderKey = languageKey\\n\\t}\\n\\trenderChatContentCalls.Add(1)\\n\\tth := a.theme\\n\\n\\tif a.activeConv == nil {\\n\\t\\treturn tr(\\\"classic.chat.no_conversation\\\")\\n\\t}\\n\\n\\t// Use full width for chat view (no breakpoint constraints)\\n\\t// Chat view should maximize available space for code, diffs, and messages\\n\\tcontentW := a.width\\n\\n\\t// Clean header - just title, no clutter\\n\\t// Sanitize title: remove newlines and truncate to fit on one line\\n\\ttitleContent := strings.ReplaceAll(a.activeConv.Title, \\\"\\\\n\\\", \\\" \\\")\\n\\ttitleContent = strings.ReplaceAll(titleContent, \\\"\\\\r\\\", \\\" \\\")\\n\\t// Use visual-width truncation to account for padding (2 on each side = 4 total)\\n\\tmaxTitleWidth := contentW - 6\\n\\tif lipgloss.Width(titleContent) > maxTitleWidth {\\n\\t\\t// Truncate by runes to avoid cutting multi-byte characters\\n\\t\\trunes := []rune(titleContent)\\n\\t\\tfor len(runes) > 0 && lipgloss.Width(string(runes)) > maxTitleWidth-1 {\\n\\t\\t\\trunes = runes[:len(runes)-1]\\n\\t\\t}\\n\\t\\ttitleContent = string(runes) + \\\"…\\\"\\n\\t}\\n\\ttitleText := Text{\\n\\t\\tContent: titleContent,\\n\\t\\tColor:   \\\"\\\",\\n\\t\\tBold:    true,\\n\\t}.Render()\\n\\n\\t// Top header/divider is intentionally disabled: pressing Tab toggles only\\n\\t// the right-side info panel (side menu). The top menu (conversation title\\n\\t// bar + divider) is no longer shown so Tab affects the side panel alone.\\n\\tvar showHeaderDivider bool = false\\n\\n\\tvar header, divider string\\n\\tif showHeaderDivider {\\n\\t\\theader = lipgloss.NewStyle().\\n\\t\\t\\tWidth(contentW).\\n\\t\\t\\tPadding(0, 2).\\n\\t\\t\\tRender(titleText + a.attachBanner())\\n\\t\\tdivider = Divider{Width: contentW, Theme: th}.Render()\\n\\t}\\n\\n\\t// =========================================================================\\n\\t// DIMENSION CALCULATIONS - Must happen BEFORE any View() calls\\n\\t// =========================================================================\\n\\n\\t// Dynamic input height - grows from minInputHeight up to an adaptive cap.\\n\\t// The cap scales with the terminal height (up to ~40% of the screen) so\\n\\t// large pastes and long multi-line messages are far more visible, while\\n\\t// always leaving the message viewport usable. A hard floor of 6 keeps the\\n\\t// old behaviour on short terminals.\\n\\tconst minInputHeight = 1\\n\\tconst absoluteMaxInputHeight = 20\\n\\tmaxInputHeight := a.height * 2 / 5 // ~40% of the screen\\n\\tif maxInputHeight < 6 {\\n\\t\\tmaxInputHeight = 6\\n\\t}\\n\\tif maxInputHeight > absoluteMaxInputHeight {\\n\\t\\tmaxInputHeight = absoluteMaxInputHeight\\n\\t}\\n\\n\\t// Check if the global status row will be shown (for height calculation).\\n\\t// Keep this predicate in sync with the render predicate below. The status\\n\\t// spinner is rendered outside the viewport cache, so it stays stable while\\n\\t// the message viewport is being rebuilt for tool/content updates.\\n\\tglobalStatusActive := (a.streamingMessage || a.isCompacting) && (a.spinner.IsActive() || a.loadingIndicator.IsActive())\\n\\tspinnerHeight := 0\\n\\tif globalStatusActive {\\n\\t\\tspinnerHeight = 2 // Spinner has Padding(1, 4, 0, 4) = 1 top padding + 1 content = 2 lines\\n\\t}\\n\\n\\t// Set input width first to calculate wrapped line count. a.width is already\\n\\t// narrowed to the effective chat width during ScreenChat rendering.\\n\\tinputWidth := a.width - chatInputHorizontalPadding\\n\\tif inputWidth < 1 {\\n\\t\\tinputWidth = 1\\n\\t}\\n\\ta.textInput.SetWidth(inputWidth)\\n\\n\\t// Calculate actual input height based on content (dynamic sizing)\\n\\t// Hide input when a modal bar is active (approval or question)\\n\\tmodalActive := a.approvalModal != nil || a.questionModal != nil || a.planQuestionModal != nil\\n\\tinputContentHeight := 0\\n\\tif !modalActive {\\n\\t\\tinputContentHeight = a.textInput.GetContentHeight()\\n\\t\\tif inputContentHeight < minInputHeight {\\n\\t\\t\\tinputContentHeight = minInputHeight\\n\\t\\t}\\n\\t\\tif inputContentHeight > maxInputHeight {\\n\\t\\t\\tinputContentHeight = maxInputHeight\\n\\t\\t}\\n\\t}\\n\\ta.textInput.SetHeight(inputContentHeight)\\n\\n\\tcountLines := func(s string) int {\\n\\t\\tif s == \\\"\\\" {\\n\\t\\t\\treturn 0\\n\\t\\t}\\n\\t\\treturn strings.Count(s, \\\"\\\\n\\\") + 1\\n\\t}\\n\\n\\tapprovalBarRendered := \\\"\\\"\\n\\tapprovalBarHeight := 0\\n\\tif a.approvalModal != nil {\\n\\t\\tapprovalBarRendered = a.approvalModal.RenderBar(a.width, a.theme)\\n\\t\\tapprovalBarHeight = countLines(approvalBarRendered)\\n\\t}\\n\\n\\t// Count actual header and divider lines for accurate space calculation\\n\\t// Only count if they will be rendered (when sidebar is visible)\\n\\theaderHeight := 0\\n\\tdividerHeight := 0\\n\\tif showHeaderDivider {\\n\\t\\theaderHeight = countLines(header)\\n\\t\\tdividerHeight = countLines(divider)\\n\\t}\\n\\n\\tquestionBarRendered := \\\"\\\"\\n\\tquestionBarHeight := 0\\n\\tif a.questionModal != nil && a.approvalModal == nil {\\n\\t\\tquestionBarRendered = a.questionModal.RenderBar(a.width, a.height, a.theme)\\n\\t\\tquestionBarHeight = countLines(questionBarRendered)\\n\\t}\\n\\n\\t// Plan approval bar (planQuestionModal) – supersedes regular questionModal at bottom\\n\\tplanQuestionBarRendered := \\\"\\\"\\n\\tplanQuestionBarHeight := 0\\n\\tif a.planQuestionModal != nil && a.approvalModal == nil {\\n\\t\\tplanQuestionBarRendered = a.planQuestionModal.RenderBar(a.width, a.height, a.theme)\\n\\t\\tplanQuestionBarHeight = countLines(planQuestionBarRendered)\\n\\t\\t// When the plan bar is active, suppress the regular question bar\\n\\t\\tquestionBarRendered = \\\"\\\"\\n\\t\\tquestionBarHeight = 0\\n\\t}\\n\\n\\tworkflowParamBarRendered := \\\"\\\"\\n\\tworkflowParamBarHeight := 0\\n\\n\\t// Edit mode hint bar height\\n\\teditHintHeight := 0\\n\\tif a.editMessageMode {\\n\\t\\teditHintHeight = 1\\n\\t}\\n\\n\\t// Queued/pending messages indicator — rendered NOW so its true line count is\\n\\t// known before we compute reservedLines and availableViewportLines.\\n\\t// This ensures the viewport shrinks to make room rather than overflowing.\\n\\tvar queuedMsgRendered string\\n\\tqueuedMsgHeight := 0\\n\\ta.pendingMsgMu.Lock()\\n\\tpendingSnapshot := make([]string, len(a.pendingUserMessages))\\n\\tcopy(pendingSnapshot, a.pendingUserMessages)\\n\\ta.pendingMsgMu.Unlock()\\n\\tif len(pendingSnapshot) > 0 {\\n\\t\\t// Style tokens — from dim→accent so the count pops and previews recede.\\n\\t\\taccentBold := lipgloss.NewStyle().\\n\\t\\t\\tForeground(lipgloss.Color(th.Accent)).\\n\\t\\t\\tBold(true)\\n\\t\\tmutedStyle := lipgloss.NewStyle().\\n\\t\\t\\tForeground(lipgloss.Color(a.theme.TextMuted))\\n\\t\\tbulletStyle := lipgloss.NewStyle().\\n\\t\\t\\tForeground(lipgloss.Color(th.Border))\\n\\t\\tdimStyle := lipgloss.NewStyle().\\n\\t\\t\\tForeground(lipgloss.Color(th.TextDim))\\n\\n\\t\\t// Effective content width inside Padding(0,2) wrapper\\n\\t\\tinnerW := a.width - 4\\n\\t\\tif innerW < 10 {\\n\\t\\t\\tinnerW = 10\\n\\t\\t}\\n\\t\\tpreviewW := innerW - 4 // \\\"  ›