					// Thinking inherits terminal default bg — see the OrderedBlocks
					// branch above for rationale. Muted fg + italic only.
					thinkingStyle := lipgloss.NewStyle().
						Foreground(lipgloss.Color(a.theme.TextMuted)).
						Italic(true)
					if len(msgLines) > 0 {
