	hasDirtyMessages := false
	for i := range messages {
		if messages[i].IsDirty() {
			hasDirtyMessages = true
			break
		}
	}

	// If no dirty messages and we have cached content, skip re-rendering
	if !hasDirtyMessages && !a.viewportContentDirty {
		return
	}

