401: func (a *App) Update(msg tea.Msg) (retModel tea.Model, retCmd tea.Cmd) {
402: 	a.observeTerminalImageCapability(msg)
403: 	a.observeTerminalCellSize(msg)
404: 	if a.bootstrapPending {
405: 		return a.updateBootstrap(msg)
406: 	}
407: 	// SAFETY NET: several paths flip spinner/loading state on (Spinner.Start,
408: 	// LoadingIndicator.Start) from handlers that historically dropped the
409: 	// Subscribe() command. If any animation is subscribed, guarantee a live
410: 	// AnimationTickMsg chain. scheduleTick dedupes, so this cannot stack
411: 	// parallel tick chains.
412: 	defer func() {
413: 		if a.animationClock == nil || !a.animationClock.IsActive() {
414: 			return
415: 		}
416: 		// TickIfIdle, not Tick: Tick() is never nil while IsActive(), so it
417: 		// would Batch on EVERY message. Each Batch costs a waiter goroutine
418: 		// plus N workers blocked on the unbuffered msg channel.
419: 		if tick := a.animationClock.TickIfIdle(); tick != nil {
420: 			if retCmd == nil {
421: 				retCmd = tick
422: 			} else {
423: 				retCmd = tea.Batch(retCmd, tick)
424: 			}
425: 		}
426: 	}()
427: 
428: 	// SAFETY NET: if View() skipped a frame to stay inside the frame budget,
429: 	// make sure one more render happens after the burst ends. Guarded by a CAS
430: 	// so at most one trailing tick is ever outstanding.
